import { memo, useMemo } from 'react';

import { TemplateSlide } from 'components';
import { useFeatureToggle } from 'hooks';
import { AISummary } from 'i18n/languages/en-US/AISummary';
import { AISummaryVolumePages } from 'pages/components/AISummary';
import { KPI_CONFIGS } from 'pages/pillars/ValueCreation/VolumePages/config';
import { useVolumePagesKpi } from 'pages/pillars/ValueCreation/VolumePages/contexts';
import { getVolumePagesPageName } from 'pages/pillars/ValueCreation/VolumePages/utils';
import { StyledExportPageSection } from 'shared/Styles/exportPages.styles';

import { pageSections } from '../../constants';
import { SummaryAiSummarySectionProps } from './types';

export const SummaryAiSummarySection = memo(
  ({ getPageByName, dataTestId }: SummaryAiSummarySectionProps) => {
    const { kpi } = useVolumePagesKpi();

    const aiSummarySubFilters = useMemo(
      () => ({
        country: 'ABI',
        viewtype: 'global',
      }),
      [],
    );

    const toggleId = KPI_CONFIGS[kpi].aiSummaryToggleId;
    const [aiSummaryEnabled, aiSummaryLoading] = useFeatureToggle(
      toggleId ?? '',
    );

    const isAiSummaryEnabled = useMemo(() => {
      if (!KPI_CONFIGS[kpi].aiSummaryPageIdentifier) return false;
      return Boolean(aiSummaryEnabled && !aiSummaryLoading);
    }, [aiSummaryEnabled, aiSummaryLoading, kpi]);

    if (!isAiSummaryEnabled) return null;

    return (
      <StyledExportPageSection data-page-name={pageSections.aiSummary}>
        <TemplateSlide
          enablePngCopy
          title=""
          page={getPageByName(pageSections.aiSummary)?.index}
          headerDivider={false}
          dataTestId={
            dataTestId ? `${dataTestId}-${pageSections.aiSummary}` : undefined
          }
          footnotes={AISummary.VolumePages.footnotes}
        >
          <AISummaryVolumePages
            pageName={getVolumePagesPageName(kpi)}
            subFilters={aiSummarySubFilters}
            summaryPageIdentifier={KPI_CONFIGS[kpi].aiSummaryPageIdentifier}
            kpiGroup={KPI_CONFIGS[kpi].kpiGroup}
            dataTestId={dataTestId ? `ai-summary-${dataTestId}` : undefined}
          />
        </TemplateSlide>
      </StyledExportPageSection>
    );
  },
);

SummaryAiSummarySection.displayName = 'SummaryAiSummarySection';
